package net.civeira.phylax.feature.observe.observedissuecomment.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;

class ObservedIssueCommentChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_issue_comment_change_set_builder() {
    ObservedIssueCommentChangeSet one =
        new ObservedIssueCommentChangeSet().uid("one").issue(ObservedIssueReference.of("one"))
            .author("one").authorName("one").text("one").createdAt(LocalDateTime
                .of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
            .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedIssueReference.of("one"), one.getIssue().get(),
        "Value must equals to the intial value");
    one.issue(ObservedIssueReference.of("two"));
    Assertions.assertEquals(ObservedIssueReference.of("two"), one.getIssue().get(),
        "Value must equals to the assigned value");
    one.unset("issue");
    Assertions.assertFalse(one.getIssue().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getAuthor().get(), "Value must equals to the intial value");
    one.author("two");
    Assertions.assertEquals("two", one.getAuthor().get(),
        "Value must equals to the assigned value");
    one.unset("author");
    Assertions.assertFalse(one.getAuthor().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getAuthorName().get(),
        "Value must equals to the intial value");
    one.authorName("two");
    Assertions.assertEquals("two", one.getAuthorName().get(),
        "Value must equals to the assigned value");
    one.unset("authorName");
    Assertions.assertFalse(one.getAuthorName().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getText().get(), "Value must equals to the intial value");
    one.text("two");
    Assertions.assertEquals("two", one.getText().get(), "Value must equals to the assigned value");
    one.unset("text");
    Assertions.assertFalse(one.getText().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getCreatedAt().get(), "Value must equals to the intial value");
    one.createdAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getCreatedAt().get(), "Value must equals to the assigned value");
    one.unset("createdAt");
    Assertions.assertFalse(one.getCreatedAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
